style.css:
@-moz-document url-prefix("https://translate.google.com/") {
html, body, #page, .content {
        background-image: url("https://th.bing.com/th/id/R.f462958dc7468c42d600185da44f82f0?rik=C86c2AUUlmiYwg&riu=http%3a%2f%2fres.cloudinary.com%2fybmedia%2fimage%2fupload%2fc_crop%2ce_improve%2ch_675%2cw_1200%2cx_0%2cy_0%2fc_fill%2cf_auto%2ch_900%2cq_auto%2cw_1600%2fv1%2fm%2fc%2f4%2fc425969beed781bc430140ef0d1a6ac840f3d23f%2fKirby-Header.webp&ehk=RD9tQGfiNQA6Pr8zUcM5FplSTvqm0E9oMSTkk0BDwk8%3d&risl=&pid=ImgRaw&r=0") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
    }
}

@-moz-document url-prefix("https://translate.google.com") {
header svg, .gb_Ed svg, [aria-label="Google Translate"] svg {
        opacity: 0 !important;
    }

    header div:first-child, .gb_Ed {
        background-image: url("https://logos-world.net/wp-content/uploads/2024/02/Kirby-Logo.png") !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center left !important;
    }
}
